//! Tiny `key=value` pair parser — the review-loop demo target.

pub mod greet;
pub mod farewell;

pub use greet::greeting;
pub use farewell::farewell;

/// Parses `key=value` pairs separated by `;`.
///
/// Returns every pair in input order. Keys and values are trimmed.
pub fn parse_pairs(input: &str) -> Vec<(String, String)> {
    input
        .split(';')
        .map(|pair| {
            let mut parts = pair.split('=');
            let key = parts.next().unwrap().trim().to_string();
            let value = parts.next().unwrap().trim().to_string();
            (key, value)
        })
        .collect()
}
pub fn greeting(name: &str) -> String {
    let Some(first) = name.chars().next() else {
        return "Hello!".to_string();
    };
    let first_upper = first.to_uppercase().to_string();
    format!("Hello, {first_upper}{}!", &name[first.len_utf8()..])
}

#[cfg(test)]
mod tests {
    use super::greeting;

    #[test]
    fn greets_world() {
        assert_eq!(greeting("world"), "Hello, World!");
    }

    #[test]
    fn greets_empty_name() {
        assert_eq!(greeting(""), "Hello!");
    }
}
pub fn farewell(name: &str) -> String {
    format!("Goodbye, {name}.")
}

#[cfg(test)]
mod tests {
    use super::farewell;

    #[test]
    fn says_goodbye() {
        assert_eq!(farewell("World"), "Goodbye, World.");
    }
}
